import * as React from "react";
import { useState } from "react";
import { Checkbox, CheckboxProps } from "./Checkbox";

export interface CheckboxOption {
  id: string;
  name: string;
  label: string;
  value: string;
  disabled?: boolean;
}

export interface CheckboxGroupProps {
  /**
   * Array of checkbox options to render.
   */
  options: CheckboxOption[];
  
  /**
   * The selected values (value from each option).
   */
  selectedValues: string[];

  /**
   * Callback when any checkbox in the group changes.
   */
  onChange?: (selected: string[]) => void;

  /**
   * Optional color prop passed to each checkbox.
   */
  colour?: CheckboxProps["colour"];

  /**
   * Layout direction for displaying checkboxes
   */
  layout?: "vertical" | "horizontal";

  /**
   * Disable all checkboxes in the group.
   */
  // disabled?: boolean;

  /**
   * Shared error message for the group.
   */
  errorText?: string;

  /**
   * Optional className for wrapper div.
   */
  className?: string;
}


export const CheckboxGroup: React.FC<CheckboxGroupProps> = ({
  options,
  selectedValues,
  onChange,
  colour = "primary",
  layout= "horizontal",
  // disabled = false,
  errorText = "",
  className = "",
}) => {
  
  
  const [internalValues, setInternalValues] = useState<string[]>([]);

  const isControlled = selectedValues !== undefined;
  const currentValues = isControlled ? selectedValues : internalValues;

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { value, checked } = event.target;

    const updated = checked
      ? [...currentValues, value]
      : currentValues.filter(val => val !== value);

    if (!isControlled) {
      setInternalValues(updated);
    }

    if (onChange) {
      onChange(updated);
    }
  };



  return (
    <div className={`checkbox-group-wrapper ${layout} ${className}`}>
      {options.map((option) => (
        <Checkbox
          key={option.value}
          id={option.value}
          name={option.name}
          value={option.value}
          label={option.label}
          checked={selectedValues?.includes(option.value)}
          onChange={handleChange}
          colour={colour}
          disabled={option.disabled}
          errorText=""
          className="group-item"
        />
      ))}

      {errorText && (
        <div className="group-error-text">
          <p className="error-text">
            <span>{errorText}</span>
          </p>
        </div>
      )}
    </div>
  );
};

export default CheckboxGroup;